export function lookAtRotation(
    eyeX: number,
    eyeY: number,
    eyeZ: number,
    targetX: number,
    targetY: number,
    targetZ: number,
    upX = 0,
    upY = 1,
    upZ = 0,
): [number, number, number, number] {
    _aim[0] = eyeX;
    _aim[1] = eyeY;
    _aim[2] = eyeZ;
    _aim[3] = targetX;
    _aim[4] = targetY;
    _aim[5] = targetZ;
    _aim[6] = upX;
    _aim[7] = upY;
    _aim[8] = upZ;
    lookAtRotationInto(_aim, _rotation);
    return [_rotation[0]!, _rotation[1]!, _rotation[2]!, _rotation[3]!];
}
