import { afterEach, expect, test } from "bun:test";
import { BaseColor, createApp, pressKey, releaseKey } from "@dylanebert/shallot";
import { ColorCube, ColorCubePlugin, GREEN, WHITE } from "./index";

const apps: Awaited<ReturnType<typeof createApp>>[] = [];
afterEach(() => {
    for (const app of apps) app.dispose();
    apps.length = 0;
});

async function scene() {
    const app = await createApp({ defaults: false, plugins: [ColorCubePlugin] });
    apps.push(app);
    const w = app.world;
    const cubes = [...w.query([ColorCube])];
    expect(cubes).toHaveLength(1);
    const color = () => Array.from(w.get(cubes[0]!, BaseColor)!.color);
    return { w, color };
}

const f = (c: readonly number[]) => c.map(Math.fround);

test("the cube starts white and stays white without input", async () => {
    const { w, color } = await scene();
    expect(color()).toEqual(f(WHITE));
    for (let i = 0; i < 30; i++) w.step(1 / 60);
    expect(color()).toEqual(f(WHITE));
});

test("other keys leave it white", async () => {
    const { w, color } = await scene();
    pressKey(w, "KeyE");
    w.step(1 / 60);
    expect(color()).toEqual(f(WHITE));
});

test("space turns it green on the same frame, and it stays green", async () => {
    const { w, color } = await scene();
    w.step(1 / 60);
    pressKey(w, "Space");
    w.step(0);
    expect(color()).toEqual(f(GREEN));
    releaseKey(w, "Space");
    for (let i = 0; i < 60; i++) w.step(1 / 60);
    expect(color()).toEqual(f(GREEN));
    pressKey(w, "Space");
    w.step(1 / 60);
    expect(color()).toEqual(f(GREEN));
});
